import '@servicenow/sdk/global'
import { Flow, trigger, wfa, action } from '@servicenow/sdk/automation'
import { StringColumn, IntegerColumn } from '@servicenow/sdk/core'

/**
 * ApprovalRules with Datapills Example
 * Demonstrates: Using wfa.dataPill() inside wfa.approvalRules()
 */
Flow(
    {
        $id: Now.ID['approval_rules_datapills_example'],
        name: 'ApprovalRules with Datapills Example',
        description: 'Demonstrates using datapills inside approval rules',
        runAs: 'system',
        flowVariables: {
            approverUser1: StringColumn({
                label: 'Approver User 1',
                mandatory: true,
            }),
            approverUser2: StringColumn({
                label: 'Approver User 2',
                mandatory: true,
            }),
            approverGroup: StringColumn({
                label: 'Approver Group',
                mandatory: true,
            }),
            approvalPercentage: IntegerColumn({
                label: 'Approval Percentage',
                mandatory: true,
            }),
        },
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['approval_rules_trigger'] },
        {
            table: 'incident',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_setting: 'both',
            run_when_user_list: [],
            run_when_user_setting: 'any',
        }
    ),
    (_params) => {
        // Initialize flow variables with approver IDs
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['init_approval_vars'],
                annotation: 'Initialize approval variables',
            },
            _params.flowVariables,
            {
                approverUser1: '62826bf03710200044e0bfc8bcbe5df1', // abel.tuter
                approverUser2: 'a8f98bb0eb32010045e1a5115206fe3a', // abraham.lincoln
                approverGroup: 'f6498860436012103cf32f0b76b8f2ce', // AI Stewards
                approvalPercentage: 75,
            }
        )

        // Create a record for approval
        const createAction = wfa.action(
            action.core.createRecord,
            {
                $id: Now.ID['create_record_for_approval'],
            },
            {
                table_name: 'incident',
                values: `short_description: "Approval Test"`,
            }
        )

        // Example 1: ApprovalRules with datapills in users array
        wfa.action(
            action.core.askForApproval,
            {
                $id: Now.ID['approval_with_user_datapills'],
                annotation: 'Ask for approval with user datapills',
            },
            {
                record: wfa.dataPill(createAction.record, 'reference'),
                table: 'incident',
                approval_reason: 'Test approval with datapills',
                approval_field: 'approval',
                journal_field: 'approval_history',
                due_date: '',
                approval_conditions: wfa.approvalRules({
                    conditionType: 'OR',
                    ruleSets: [
                        {
                            action: 'Approves',
                            conditionType: 'AND',
                            rules: [
                                [
                                    {
                                        ruleType: 'Any',
                                        users: [
                                            wfa.dataPill(_params.flowVariables.approverUser1, 'string'),
                                            wfa.dataPill(_params.flowVariables.approverUser2, 'string'),
                                            wfa.dataPill(_params.trigger.current.sys_created_by, 'string'),
                                        ],
                                        groups: [],
                                        manual: false,
                                    },
                                ],
                            ],
                        },
                    ],
                }),
            }
        )

        // Example 2: ApprovalRules with datapills in groups array
        wfa.action(
            action.core.askForApproval,
            {
                $id: Now.ID['approval_with_group_datapills'],
                annotation: 'Ask for approval with group datapills',
            },
            {
                record: wfa.dataPill(createAction.record, 'reference'),
                table: 'incident',
                approval_reason: 'Group approval test',
                approval_field: 'approval',
                journal_field: 'approval_history',
                due_date: '',
                approval_conditions: wfa.approvalRules({
                    conditionType: 'OR',
                    ruleSets: [
                        {
                            action: 'Approves',
                            conditionType: 'AND',
                            rules: [
                                [
                                    {
                                        ruleType: 'All',
                                        users: ['62826bf03710200044e0bfc8bcbe5df1'],
                                        groups: [wfa.dataPill(_params.flowVariables.approverGroup, 'string')],
                                        manual: false,
                                    },
                                ],
                            ],
                        },
                    ],
                }),
            }
        )

        // Example 3: ApprovalRules with percent rule using datapill
        wfa.action(
            action.core.askForApproval,
            {
                $id: Now.ID['approval_with_percent_datapill'],
                annotation: 'Ask for approval with percent datapill',
            },
            {
                record: wfa.dataPill(createAction.record, 'reference'),
                table: 'incident',
                approval_reason: 'Percentage approval test',
                approval_field: 'approval',
                journal_field: 'approval_history',
                due_date: '',
                approval_conditions: wfa.approvalRules({
                    conditionType: 'OR',
                    ruleSets: [
                        {
                            action: 'Approves',
                            conditionType: 'AND',
                            rules: [
                                [
                                    {
                                        ruleType: 'Percent',
                                        percent: wfa.dataPill(_params.flowVariables.approvalPercentage, 'integer'),
                                        users: [],
                                        groups: ['f6498860436012103cf32f0b76b8f2ce'],
                                        manual: false,
                                    },
                                ],
                            ],
                        },
                    ],
                }),
            }
        )

        wfa.action(
            action.core.log,
            {
                $id: Now.ID['log_for_approval_output'],
            },
            {
                log_level: 'info',
                log_message: 'Test log',
            }
        )

        // Example 4: ApprovalRules with complex datapills (action outputs, trigger, flow vars)
        wfa.action(
            action.core.askForApproval,
            {
                $id: Now.ID['approval_with_complex_datapills'],
                annotation: 'Ask for approval with complex datapills from multiple sources',
            },
            {
                record: wfa.dataPill(_params.trigger.current, 'reference'),
                table: 'incident',
                approval_reason: 'Complex approval test',
                approval_field: 'approval',
                journal_field: 'approval_history',
                due_date: '',
                approval_conditions: wfa.approvalRules({
                    conditionType: 'OR',
                    ruleSets: [
                        {
                            action: 'Approves',
                            conditionType: 'AND',
                            rules: [
                                [
                                    {
                                        ruleType: 'Any',
                                        users: [
                                            wfa.dataPill(_params.flowVariables.approverUser1, 'string'),
                                            wfa.dataPill(_params.trigger.current.sys_created_by, 'string'),
                                        ],
                                        groups: [wfa.dataPill(_params.flowVariables.approverGroup, 'string')],
                                        manual: false,
                                    },
                                ],
                                [
                                    {
                                        ruleType: 'Count',
                                        count: 2,
                                        users: [
                                            wfa.dataPill(_params.flowVariables.approverUser2, 'string'),
                                            '0a826bf03710200044e0bfc8bcbe5d7a',
                                        ],
                                        groups: [],
                                        manual: false,
                                    },
                                ],
                            ],
                        },
                        {
                            action: 'Rejects',
                            conditionType: 'AND',
                            rules: [
                                [
                                    {
                                        ruleType: 'Any',
                                        users: [wfa.dataPill(_params.flowVariables.approverUser1, 'string')],
                                        groups: [],
                                        manual: false,
                                    },
                                ],
                            ],
                        },
                    ],
                }),
            }
        )

        wfa.action(
            action.core.log,
            {
                $id: Now.ID['log_approval_rules_completion'],
            },
            {
                log_level: 'info',
                log_message: 'ApprovalRules with datapills test completed',
            }
        )
    }
)
